p=r/'effects/fire_status.gd';s=p.read_text(encoding='utf-8-sig')
s=s.replace('if settings.duration <= 0.0 or settings.damage <= 0.0: return','if settings.duration <= 0.0: return')
s=s.replace('source_stats.get_fire_interval(settings.tick_interval) if source_stats else settings.tick_interval','source_stats.get_fire_interval() if source_stats else StatusEffect.BASE_FIRE_INTERVAL')
s=s.replace('source_stats.get_fire_interval(settings.tick_interval) if source_stats else maxf(0.05, settings.tick_interval)','source_stats.get_fire_interval() if source_stats else StatusEffect.BASE_FIRE_INTERVAL')
s=s.replace('\tburn.hit.setup(settings.damage * (source_stats.get_effect_multiplier() * source_stats.final_multiplier("damage_percent") if source_stats and not damage_scaled else 1.0), false, 0.0, template.source)','\tvar player_fire := template.source is Player and source_stats != null\n\tvar tick_damage: float = source_stats.get_burning_damage() if player_fire else maxf(0.0, settings.damage * (source_stats.get_effect_multiplier() * source_stats.final_multiplier("damage_percent") if source_stats and not damage_scaled else 1.0))\n\tburn.hit.setup(tick_damage, false, 0.0, template.source)')
s=s.replace('"damage": entry.damage * multiplier','"damage": source_stats.get_burning_damage() if player_fire else entry.damage * multiplier')
p.write_text(s,encoding='utf-8')
